import{_ as t,o as i,c as a,ao as s}from"./chunks/framework.DHUAaJOT.js";const f=JSON.parse('{"title":"Solvers","description":"","frontmatter":{},"headers":[],"relativePath":"manual/solvers.md","filePath":"manual/solvers.md","lastUpdated":null}'),o={name:"manual/solvers.md"};function l(r,e,n,p,d,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="solvers" tabindex="-1">Solvers <a class="header-anchor" href="#solvers" aria-label="Permalink to &quot;Solvers {#solvers}&quot;">​</a></h1><h2 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to &quot;Overview {#Overview}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Function</th><th style="text-align:left;">Gives</th><th style="text-align:left;">Assumptions</th></tr></thead><tbody><tr><td style="text-align:left;">Bloch-Torrey equation</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_btpde"><code>solve_btpde</code></a></td><td style="text-align:left;">magnetization, signal</td><td style="text-align:left;">none (reference)</td></tr><tr><td style="text-align:left;">Homogenized ADC</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_hadc"><code>solve_hadc</code></a>, <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_hadc_tensors"><code>solve_hadc_tensors</code></a></td><td style="text-align:left;">ADC, apparent diffusion tensor</td><td style="text-align:left;">impermeable membranes, low b</td></tr><tr><td style="text-align:left;">Matrix formalism</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_laplace"><code>solve_laplace</code></a>, <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_mf"><code>solve_mf</code></a></td><td style="text-align:left;">magnetization, signal</td><td style="text-align:left;">truncated eigenfunction basis</td></tr><tr><td style="text-align:left;">Matrix formalism, effective tensor</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.compute_mf_diffusion_tensor"><code>compute_mf_diffusion_tensor</code></a></td><td style="text-align:left;">apparent diffusion tensor</td><td style="text-align:left;">low b</td></tr><tr><td style="text-align:left;">Kärger model</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_karger"><code>solve_karger</code></a></td><td style="text-align:left;">signal</td><td style="text-align:left;">well mixed compartments</td></tr><tr><td style="text-align:left;">Short diffusion time approximation</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.compute_adc_sta"><code>compute_adc_sta</code></a></td><td style="text-align:left;">ADC</td><td style="text-align:left;">short diffusion times</td></tr><tr><td style="text-align:left;">Analytical matrix formalism</td><td style="text-align:left;"><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_analytical_mf"><code>solve_analytical_mf</code></a></td><td style="text-align:left;">signal</td><td style="text-align:left;">layered plates, cylinders, spheres</td></tr></tbody></table><p>The ADC follows from the signals of several b-values with <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.fit_adc"><code>fit_adc</code></a>, and apparent diffusion tensors from ADCs in several directions with <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.fit_tensors"><code>fit_tensors</code></a>. See <a href="/SpinDoctor.jl/previews/PR49/examples/generated/compare_adcs#adc-methods">Apparent diffusion coefficients</a> for a comparison.</p><h2 id="Time-stepping" tabindex="-1">Time stepping <a class="header-anchor" href="#Time-stepping" aria-label="Permalink to &quot;Time stepping {#Time-stepping}&quot;">​</a></h2><p><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_btpde"><code>solve_btpde</code></a> uses a <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.ThetaSolver"><code>ThetaSolver</code></a> by default (Crank-Nicolson): one sparse factorization per interval for PGSE-like sequences, and GMRES with a preconditioner for other gradients. The time step is a thousandth of the echo time by default:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve_btpde</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, matrices, gradient, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ThetaSolver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; timestep </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> compute_signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(matrices</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">M, u)</span></span></code></pre></div><p>The adaptive ODE solvers of OrdinaryDiffEq are also available, after loading one of its solver packages, for example <code>using OrdinaryDiffEqBDF</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve_btpde</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, matrices, gradient, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">QNDF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); abstol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e-8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, reltol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e-6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="Periodic-boundary-conditions" tabindex="-1">Periodic boundary conditions <a class="header-anchor" href="#Periodic-boundary-conditions" aria-label="Permalink to &quot;Periodic boundary conditions {#Periodic-boundary-conditions}&quot;">​</a></h2><p>The meshes of the samples of periodic tissue (<a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.PeriodicBoxECS"><code>PeriodicBoxECS</code></a>, <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.VoronoiSetup"><code>VoronoiSetup</code></a>) are periodic. With</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">matrices </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> assemble_matrices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model; periodic </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>the points on opposite faces of the box are identified, and <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_btpde"><code>solve_btpde</code></a> (with <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.ThetaSolver"><code>ThetaSolver</code></a>) and <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_hadc"><code>solve_hadc</code></a> use periodic boundary conditions instead of impermeable box faces (see <a href="/SpinDoctor.jl/previews/PR49/theory/btpde#periodic-theory">Periodic boundary conditions</a>). The signals and ADCs then do not depend on the position of the cells in the box, and the water of the ECS is not trapped by the box. See <a href="/SpinDoctor.jl/previews/PR49/examples/generated/periodic_tissue#periodic">Dense tissue with periodic boundary conditions</a> and <a href="/SpinDoctor.jl/previews/PR49/examples/generated/white_matter#white-matter">White matter</a>.</p><h2 id="Callbacks" tabindex="-1">Callbacks <a class="header-anchor" href="#Callbacks" aria-label="Permalink to &quot;Callbacks {#Callbacks}&quot;">​</a></h2><p><a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.solve_btpde"><code>solve_btpde</code></a> calls the <code>callbacks</code> after each time step: <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.Printer"><code>Printer</code></a> prints information, <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.VTKWriter"><code>VTKWriter</code></a> saves the magnetization for <a href="https://www.paraview.org" target="_blank" rel="noreferrer">ParaView</a>, and <a href="/SpinDoctor.jl/previews/PR49/api#SpinDoctor.Plotter"><code>Plotter</code></a> plots it (see <a href="/SpinDoctor.jl/previews/PR49/manual/output#Plotting-and-output">Plotting and output</a>).</p>`,15)])])}const k=t(o,[["render",l]]);export{f as __pageData,k as default};
